import { encodeFunctionData, keccak256, parseAbi } from "viem";

export const TIMESTAMP_GUARD_ABI = parseAbi([
  "error TooEarly(uint256 currentTimestamp, uint256 notBeforeTimestamp)",
  "function requireTimestamp(uint256 notBeforeTimestamp) view"
]);

// Compiled from contracts/TimestampGuard.sol with solc 0.8.30, optimizer runs=200.
export const TIMESTAMP_GUARD_DEPLOYMENT_BYTECODE = "";
export const TIMESTAMP_GUARD_RUNTIME_BYTECODE = "";
export const TIMESTAMP_GUARD_RUNTIME_CODE_HASH = keccak256(TIMESTAMP_GUARD_RUNTIME_BYTECODE);

export function encodeTimestampGuardCall(notBeforeTimestamp) {
  return encodeFunctionData({
    abi: TIMESTAMP_GUARD_ABI,
    functionName: "requireTimestamp",
    args: [BigInt(notBeforeTimestamp)]
  });
}

export function timestampGuardCodeMatches(code) {
  return typeof code === "string" && code !== "0x" && keccak256(code) === TIMESTAMP_GUARD_RUNTIME_CODE_HASH;
}
